359	// List enumerates local checkpoint refs and reads each root summary, sorted most
360	// recent first. Storage-level listing is local-refs-only for now (no remote
361	// enumeration), matching the issue's first-version scope.
362	func (s *gitRefsStore) List(ctx context.Context) ([]CheckpointInfo, error) {
363		if err := ctx.Err(); err != nil {
364			return nil, err //nolint:wrapcheck // Propagating context cancellation
365		}
