378			}
379			commit, commitErr := s.repo.CommitObject(ref.Hash())
380			if commitErr != nil {
381				return nil //nolint:nilerr // skip unreadable refs, keep listing
382			}
383			tree, treeErr := commit.Tree()
384			if treeErr != nil {
385				return nil //nolint:nilerr // skip unreadable refs, keep listing
386			}
